from pathlib import Path
import shutil,json,pymupdf as fitz
root=Path('.')
for folder in ['assets/css','assets/js','portfolio','config']: (root/folder).mkdir(parents=True,exist_ok=True)
shutil.copyfile('tools/profile-image-0.jpg','assets/images/logo/pavan-sai.jpg')
projects=[('gear-pair','Gear pair','Mechanical','GEAR PAIR SAMPLE DWG.pdf','Gear geometry, sectional views and component dimensions.'),('screw-conveyor','Screw conveyor assembly','Mechanical','SAMPLE 1.pdf','Assembly views and component detailing for a screw conveyor.'),('abrasive-hopper','Abrasive storage hopper','Mechanical','SAMPLE 2.pdf','Fabrication details, sectional views and a material schedule.'),('blast-cabinet','Blast housing cabinet','Mechanical','SAMPLE 3.pdf','Equipment fabrication drawing with elevations and sections.'),('drive-gearbox','Drive gearbox assembly','Mechanical','SAMPLE 4.pdf','Assembly and sectional views for a conveyor drive gearbox.'),('sprocket','Sprocket details','Mechanical','SPROCKET.pdf','Sprocket tooth profiles, dimensions and machining details.'),('structural-shed','Structural shed','Structural','STRL-SAMPLE-DWG.pdf','Roof plan at purlin level and structural shed cladding elevation.')]
data=[]
for id,title,category,file,desc in projects:
 shutil.copyfile(Path('requirement_docs/SAMPLE DWGS')/file,Path('assets/pdfs')/file)
 d=fitz.open(Path('assets/pdfs')/file); page=d[0]; page.set_rotation(90); pix=page.get_pixmap(matrix=fitz.Matrix(0.65,0.65)); pix.save(f'assets/images/portfolio/{id}.png')
 data.append(dict(id=id,title=title,category=category,file=file,description=desc,pages=len(d),size=round((Path('assets/pdfs')/file).stat().st_size/1024)))
