def service_cards(full=False):
 return ''.join(f'<article class="service"><span class="number">{n}</span><h3>{title}</h3><p>{desc}</p>'+('<ul>'+''.join(f'<li>{x}</li>' for x in features.split(';'))+'</ul>' if full else '')+'</article>' for n,title,desc,features in services)
def cards(items):
 return ''.join(f'''<article class="work-card" data-category="{p['category']}"><a class="drawing" href="portfolio/viewer.html?project={p['id']}" aria-label="View {p['title']}"><img src="assets/images/portfolio/{p['id']}.png" alt="{p['title']} sample engineering drawing" width="900" height="640" loading="lazy"></a><div class="work-body"><span class="eyebrow">{p['category']} / Sample drawing</span><h3>{p['title']}</h3><p>{p['description']}</p><div class="work-links"><a href="portfolio/viewer.html?project={p['id']}">View project <span aria-hidden="true">↗</span></a><a href="assets/pdfs/{p['file']}" target="_blank" rel="noopener">Open PDF</a></div></div></article>''' for p in items)
