 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | Pavan Sai Engineering Services</title><meta name="description" content="{description}"><meta property="og:title" content="{title} | Pavan Sai Engineering Services"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><meta property="og:image" content="{prefix}assets/images/logo/pavan-sai.jpg"><meta name="theme-color" content="#123444"><link rel="icon" href="{prefix}assets/images/logo/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/css/style.css"><script src="{prefix}assets/js/main.js" defer></script></head><body>{header}<main id="main">{body}</main>{footer}</body></html>'''
